      JSON.parse(raw || "{}");
      const r = spawnSync("df", ["-kP"], { encoding: "utf8", timeout: 4000 });
      if (r.error) throw new Error("df failed: " + r.error.message);
      if (r.status !== 0) throw new Error("df exit " + r.status + ": " + String(r.stderr || "").trim());
