#!/usr/bin/env node
import { spawnSync } from "node:child_process";

// readelf -d output rows look like:
//   0x0000000000000001 (NEEDED)             Shared library: [libc.so.6]
//   0x000000000000000f (RPATH)              Library rpath: [/opt/lib]
const TAG_RE = /^\s*0x[0-9a-fA-F]+\s+\(([^)]+)\)\s+(.*)$/;

function parse(text) {
  const entries = [];
  const needed = [];
  const rpath = [];
  const runpath = [];
  for (const line of text.split(/\r?\n/)) {
    const m = TAG_RE.exec(line);
    if (!m) continue;
    const tag = m[1];
    const rest = m[2].trim();
    let value = rest;
    const bracket = rest.match(/\[(.*)\]\s*$/);
    if (bracket) value = bracket[1];
    entries.push({ tag, value });
    if (tag === "NEEDED") needed.push(value);
    else if (tag === "RPATH") rpath.push(value);
    else if (tag === "RUNPATH") runpath.push(value);
  }
  return { entries, needed, rpath, runpath };
}

function main() {
  let raw = "";
  process.stdin.on("data", (d) => (raw += d.toString()));
  process.stdin.on("end", () => {
    try {
      const { path } = JSON.parse(raw || "{}");
      if (typeof path !== "string" || !path) throw new Error("input.path must be a non-empty string");
      if (path.startsWith("-")) throw new Error("input.path must not start with '-'");
      const r = spawnSync("readelf", ["-d", "--", path], { encoding: "utf8", timeout: 4000 });
      if (r.error) throw new Error("readelf failed: " + r.error.message);
      if (r.status !== 0) throw new Error("readelf exit " + r.status + ": " + String(r.stderr || "").trim());
      const parsed = parse(r.stdout);
      process.stdout.write(JSON.stringify({ path, needed: parsed.needed, rpath: parsed.rpath, runpath: parsed.runpath, entries: parsed.entries }));
    } catch (err) {
      process.stderr.write(String(err && err.message ? err.message : err));
      process.exit(1);
    }
  });
}
main();

#!/usr/bin/env node
import { spawnSync } from "node:child_process";

function parseHeader(text) {
  const out = {};
  for (const line of text.split(/\r?\n/)) {
    const m = line.match(/^\s{2}([A-Za-z][^:]*):\s+(.*)$/);
    if (!m) continue;
    out[m[1].trim()] = m[2].trim();
  }
  return out;
}

function pick(field) {
  return typeof field === "string" ? field.split("(")[0].trim() : "";
}

function main() {
  let raw = "";
  process.stdin.on("data", (d) => (raw += d.toString()));
  process.stdin.on("end", () => {
    try {
      const { path } = JSON.parse(raw || "{}");
      if (typeof path !== "string" || !path) throw new Error("input.path must be a non-empty string");
      if (path.startsWith("-")) throw new Error("input.path must not start with '-'");

      const r = spawnSync("readelf", ["-h", "--", path], { encoding: "utf8", timeout: 4000 });
      if (r.error) throw new Error("readelf failed: " + r.error.message);
      if (r.status !== 0) {
        const err = String(r.stderr || "").trim();
        throw new Error("readelf exit " + r.status + (err ? ": " + err : ""));
      }

      const h = parseHeader(r.stdout);
      if (!h["Class"]) throw new Error("not an ELF file (no Class field in readelf output)");

      const numOrZero = (s) => {
        const n = parseInt(String(s || "").trim(), 10);
        return Number.isFinite(n) ? n : 0;
      };

      process.stdout.write(JSON.stringify({
        path,
        class: pick(h["Class"]),
        data: pick(h["Data"]),
        osabi: pick(h["OS/ABI"]),
        type: pick(h["Type"]),
        machine: pick(h["Machine"]),
        entry: (h["Entry point address"] || "").trim(),
        programHeaderCount: numOrZero(h["Number of program headers"]),
        sectionHeaderCount: numOrZero(h["Number of section headers"]),
        raw: r.stdout.trim()
      }));
    } catch (err) {
      process.stderr.write(String(err && err.message ? err.message : err));
      process.exit(1);
    }
  });
}
main();

#!/usr/bin/env node
import { spawnSync } from "node:child_process";

// readelf -rW output:
//   Relocation section '.rela.dyn' at offset 0x640 contains 3 entries:
//     Offset          Info           Type           Sym. Value    Sym. Name + Addend
//   0000000000003d98  0000000000000008 R_X86_64_RELATIVE                    1140
const SEC_RE = /^Relocation section '([^']+)'/;
const ROW_RE = /^\s*([0-9a-fA-F]+)\s+([0-9a-fA-F]+)\s+(\S+)\s+(.*)$/;

function parse(text) {
  const sections = [];
  let current = null;
  for (const line of text.split(/\r?\n/)) {
    const sm = SEC_RE.exec(line);
    if (sm) {
      current = { section: sm[1], entries: [] };
      sections.push(current);
      continue;
    }
    if (!current) continue;
    const m = ROW_RE.exec(line);
    if (!m) continue;
    const tail = (m[4] || "").trim();
    // Symbol is the first token in the tail that isn't purely hex, if any.
    const tokens = tail.split(/\s+/);
    const symbol = tokens.length > 0 && !/^[0-9a-fA-F]+$/.test(tokens[0]) ? tokens[0] : "";
    current.entries.push({ offset: m[1], info: m[2], type: m[3], symbol });
  }
  return sections;
}

function main() {
  let raw = "";
  process.stdin.on("data", (d) => (raw += d.toString()));
  process.stdin.on("end", () => {
    try {
      const { path } = JSON.parse(raw || "{}");
      if (typeof path !== "string" || !path) throw new Error("input.path must be a non-empty string");
      if (path.startsWith("-")) throw new Error("input.path must not start with '-'");
      const r = spawnSync("readelf", ["-r", "-W", "--", path], { encoding: "utf8", timeout: 4000, maxBuffer: 64 * 1024 * 1024 });
      if (r.error) throw new Error("readelf failed: " + r.error.message);
      if (r.status !== 0) throw new Error("readelf exit " + r.status + ": " + String(r.stderr || "").trim());
      process.stdout.write(JSON.stringify({ path, sections: parse(r.stdout) }));
    } catch (err) {
      process.stderr.write(String(err && err.message ? err.message : err));
      process.exit(1);
    }
  });
}
main();

#!/usr/bin/env node
import { spawnSync } from "node:child_process";

// readelf -S -W output sample (one line per section after the column header):
//   [ 1] .interp           PROGBITS        0000000000000318 000318 00001c 00   A  0   0  1
// We only need the leading fields; extra trailing columns are ignored.
const SECTION_RE = /^\s*\[\s*\d+\]\s+(\S+)\s+(\S+)\s+([0-9a-fA-F]+)\s+([0-9a-fA-F]+)\s+([0-9a-fA-F]+)\s+[0-9a-fA-F]+\s*(.*?)\s*$/;

function parseSections(text) {
  const out = [];
  let inSections = false;
  for (const line of text.split(/\r?\n/)) {
    if (/^Section Headers:/.test(line)) { inSections = true; continue; }
    if (!inSections) continue;
    if (/^\s*\[Nr\]/.test(line)) continue;
    if (/^\s*Key to Flags:/.test(line)) break;
    const m = SECTION_RE.exec(line);
    if (!m) continue;
    const tail = (m[6] || "").trim();
    // tail can be "0   0  1" (no flags), "A  0   0  1" (flag A + links), "AX  0   0  1", etc.
    // flags are non-numeric short tokens at the start of tail
    const flagParts = [];
    for (const token of tail.split(/\s+/)) {
      if (/^[A-Z]+$/.test(token)) flagParts.push(token);
      else break;
    }
    out.push({
      name: m[1],
      type: m[2],
      address: m[3],
      offset: m[4],
      size: m[5],
      flags: flagParts.join("")
    });
  }
  return out;
}

function main() {
  let raw = "";
  process.stdin.on("data", (d) => (raw += d.toString()));
  process.stdin.on("end", () => {
    try {
      const { path } = JSON.parse(raw || "{}");
      if (typeof path !== "string" || !path) throw new Error("input.path must be a non-empty string");
      if (path.startsWith("-")) throw new Error("input.path must not start with '-'");

      const r = spawnSync("readelf", ["-S", "-W", "--", path], { encoding: "utf8", timeout: 4000 });
      if (r.error) throw new Error("readelf failed: " + r.error.message);
      if (r.status !== 0) {
        const err = String(r.stderr || "").trim();
        throw new Error("readelf exit " + r.status + (err ? ": " + err : ""));
      }

      const sections = parseSections(r.stdout);
      if (sections.length === 0) throw new Error("no section headers found (not an ELF file?)");

      process.stdout.write(JSON.stringify({ path, sections }));
    } catch (err) {
      process.stderr.write(String(err && err.message ? err.message : err));
      process.exit(1);
    }
  });
}
main();

#!/usr/bin/env node
import { spawnSync } from "node:child_process";

// readelf -sW rows:
//    Num:    Value          Size Type    Bind   Vis      Ndx Name
//     12: 0000000000001000    42 FUNC    GLOBAL DEFAULT   12 main
const SYM_RE = /^\s*\d+:\s+[0-9a-fA-F]+\s+\d+\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(.*)$/;

function parse(text) {
  const out = [];
  for (const line of text.split(/\r?\n/)) {
    if (/^\s*Num:/.test(line)) continue;
    if (/^Symbol table /.test(line)) continue;
    const m = SYM_RE.exec(line);
    if (!m) continue;
    out.push({
      type: m[1], bind: m[2], vis: m[3], ndx: m[4],
      name: (m[5] || "").trim()
    });
  }
  return out;
}

function main() {
  let raw = "";
  process.stdin.on("data", (d) => (raw += d.toString()));
  process.stdin.on("end", () => {
    try {
      const input = JSON.parse(raw || "{}");
      const path = input.path;
      if (typeof path !== "string" || !path) throw new Error("input.path must be a non-empty string");
      if (path.startsWith("-")) throw new Error("input.path must not start with '-'");
      const args = input.defined ? ["-s", "-W", "--", path] : ["-s", "-W", "--", path];
      const r = spawnSync("readelf", args, { encoding: "utf8", timeout: 4000, maxBuffer: 64 * 1024 * 1024 });
      if (r.error) throw new Error("readelf failed: " + r.error.message);
      if (r.status !== 0) throw new Error("readelf exit " + r.status + ": " + String(r.stderr || "").trim());
      let symbols = parse(r.stdout);
      if (input.defined) symbols = symbols.filter((s) => s.ndx !== "UND");
      process.stdout.write(JSON.stringify({ path, count: symbols.length, symbols }));
    } catch (err) {
      process.stderr.write(String(err && err.message ? err.message : err));
      process.exit(1);
    }
  });
}
main();

#!/usr/bin/env python3
import json
import sys

def main() -> None:
    raw = sys.stdin.read() or "{}"
    try:
        payload = json.loads(raw)
    except json.JSONDecodeError as exc:
        print(f"invalid JSON input: {exc}", file=sys.stderr)
        sys.exit(1)

    events = payload.get("events")
    if not isinstance(events, list):
        print("input.events must be a list", file=sys.stderr)
        sys.exit(1)

    seen = set()
    ordered = []
    for event in events:
        if not isinstance(event, dict):
            continue
        ip = event.get("ip")
        if not isinstance(ip, str):
            continue
        if ip in seen:
            continue
        seen.add(ip)
        ordered.append(ip)

    sys.stdout.write(json.dumps({"ips": ordered}))

if __name__ == "__main__":
    main()

